SELECT 
FROM sys_agent_task_step
WHERE task_id = #{taskId}
  AND step_order = #{stepOrder}
LIMIT 1

SELECT COUNT(1)
FROM sys_agent_task_step
WHERE task_id = #{taskId}
  AND input_fingerprint = #{fingerprint}
  AND status IN ('RUNNING', 'WAITING_CONFIRMATION', 'CONFIRMING', 'COMPLETED')
